// Valida el id y lee el item. Solo se envía a revisión lo que está en ready_for_review
const id = String($input.first().json.content_item_id ?? '').trim().toLowerCase();
if (!/^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/.test(id)) throw new Error('validation: content_item_id no es un UUID');
const key = $env.SUPABASE_SERVICE_ROLE_KEY;
const [item] = await this.helpers.httpRequest({ method: 'GET', url: `${$env.SUPABASE_URL}/rest/v1/content_items`, json: true, timeout: 30000,
  headers: { apikey: key, Authorization: `Bearer ${key}` }, qs: { select: '*', id: `eq.${id}` } });
if (!item) throw new Error('validation: el content_item no existe');
if (item.status !== 'ready_for_review') throw new Error(`validation: el item está en «${item.status}», no en ready_for_review`);
return [{ json: { item, started_at: new Date().toISOString() } }];

const tg = (method, body) => this.helpers.httpRequest({ method: 'POST', url: `https://api.telegram.org/bot${$env.TELEGRAM_BOT_TOKEN}/${method}`, body, json: true, timeout: 30000 });
// Arma el mensaje de revisión y lo manda al aprobador con los 4 botones. Texto en HTML con todo escapado: los captions traen **negrita**, guiones bajos y símbolos
const { item } = $input.first().json;
const esc = (s) => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const bold = (s) => esc(s).replace(/\*\*(.+?)\*\*/g, '<b>$1</b>');
const tags = (arr) => (Array.isArray(arr) ? arr : []).map((h) => `#${String(h).replace(/^#/, '')}`).join(' ');
const ig = String(item.caption_instagram ?? '(sin caption)');
const igTags = tags(item.hashtags_instagram);
// El pie de foto de Telegram admite 1.024 caracteres de texto visible; el resto va completo en el segundo mensaje
const head = '📋 Nuevo contenido para revisar\n\nInstagram:\n';
const budget = 1000 - head.length - igTags.length - 2;
const plain = ig.replace(/\*\*/g, '');
const truncated = plain.length > budget;
const igHtml = truncated ? esc(plain.slice(0, Math.max(budget - 1, 0))) + '…' : bold(ig);
const caption = `📋 <b>Nuevo contenido para revisar</b>\n\n<b>Instagram:</b>\n${igHtml}\n${esc(igTags)}`;
const details = [
  truncated ? `<b>Instagram (completo):</b>\n${bold(ig)}\n` : '',
  `<b>YouTube:</b>\n🎬 ${esc(item.title_youtube || '(sin título)')}\n${bold(item.caption_youtube || '(sin caption)')}\n`,
  `<b>TikTok:</b>\n${bold(item.caption_tiktok || '(sin caption)')}\n${esc(tags(item.hashtags_tiktok))}`,
].filter(Boolean).join('\n').slice(0, 4000);
const id = item.id;
const reply_markup = { inline_keyboard: [
  [{ text: '✅ Aprobar', callback_data: `approve_${id}` }, { text: '✏️ Editar', callback_data: `edit_${id}` }],
  [{ text: '🔄 Regenerar', callback_data: `regenerate_${id}` }, { text: '❌ Descartar', callback_data: `discard_${id}` }],
  [{ text: '💬 Objetar', callback_data: `object_${id}` }, { text: '✔️ Resolver objeción', callback_data: `resolve_${id}` }],
] };
const chat_id = $env.TELEGRAM_APPROVER_CHAT_ID;
// La imagen se reenvía por su file_id: Telegram no descarga nada y la URL con el token del bot nunca sale de n8n
const ref = String(item.raw_asset_url ?? '');
const fileId = ref.startsWith('telegram:') ? ref.slice('telegram:'.length) : null;
if (fileId && item.asset_type === 'image') await tg('sendPhoto', { chat_id, photo: fileId, caption, parse_mode: 'HTML', reply_markup });
else if (fileId && item.asset_type === 'video') await tg('sendVideo', { chat_id, video: fileId, caption, parse_mode: 'HTML', reply_markup });
else await tg('sendMessage', { chat_id, text: caption, parse_mode: 'HTML', reply_markup });
await tg('sendMessage', { chat_id, text: details, parse_mode: 'HTML' });
return [{ json: { content_item_id: id, started_at: $('Leer item').first().json.started_at, truncated } }];

// Deja la fila del paso review_send en pipeline_steps; el intento es el último + 1
const r = $input.first().json;
const key = $env.SUPABASE_SERVICE_ROLE_KEY;
const headers = { apikey: key, Authorization: `Bearer ${key}`, 'Content-Type': 'application/json' };
const base = `${$env.SUPABASE_URL}/rest/v1/pipeline_steps`;
const prev = await this.helpers.httpRequest({ method: 'GET', url: base, headers, json: true, timeout: 30000,
  qs: { content_item_id: `eq.${r.content_item_id}`, step: 'eq.review_send', select: 'attempt', order: 'attempt.desc', limit: 1 } });
await this.helpers.httpRequest({ method: 'POST', url: base, headers: { ...headers, Prefer: 'return=minimal' }, json: true, timeout: 30000,
  body: { content_item_id: r.content_item_id, step: 'review_send', attempt: (prev?.[0]?.attempt ?? 0) + 1, status: 'succeeded', started_at: r.started_at, finished_at: new Date().toISOString(), n8n_execution_id: String($execution.id) } });
return [{ json: { ok: true, content_item_id: r.content_item_id, sent: true, truncated: r.truncated } }];

const tg = (method, body) => this.helpers.httpRequest({ method: 'POST', url: `https://api.telegram.org/bot${$env.TELEGRAM_BOT_TOKEN}/${method}`, body, json: true, timeout: 30000 });
// Si el envío falla el item sigue en ready_for_review: queda constancia y aviso al administrador
const raw = $input.first().json;
const mask = (s) => String(s).replace(/bot\d+:[A-Za-z0-9_-]+/g, 'bot***');
const message = mask(raw.error?.message ?? raw.error ?? raw.message ?? 'Error sin mensaje').slice(0, 2000);
const prefix = (message.match(/^([a-z_]+):/) ?? [])[1];
// Sin prefijo propio, la etapa es el último nodo que llegó a ejecutarse: Registrar paso y Leer item hablan con Supabase; Enviar propuesta, con Telegram
const error_type = prefix ?? ($('Registrar paso').isExecuted ? 'supabase' : $('Enviar propuesta').isExecuted ? 'telegram_http' : $('Leer item').isExecuted ? 'supabase' : 'execution_error');
const entrada = $('Entrada').first(0, 0)?.json ?? {};
const id = /^[0-9a-f-]{36}$/i.test(String(entrada.content_item_id ?? '')) ? String(entrada.content_item_id).toLowerCase() : null;
const key = $env.SUPABASE_SERVICE_ROLE_KEY;
const headers = { apikey: key, Authorization: `Bearer ${key}`, 'Content-Type': 'application/json', Prefer: 'return=minimal' };
const attempt = async (fn) => { try { await fn(); return true; } catch (err) { return false; } };
const started = $('Leer item').isExecuted ? ($('Leer item').first(0, 0)?.json?.started_at ?? new Date().toISOString()) : new Date().toISOString();
if (id && $('Leer item').isExecuted) {
  await attempt(async () => {
    const prev = await this.helpers.httpRequest({ method: 'GET', url: `${$env.SUPABASE_URL}/rest/v1/pipeline_steps`, headers, json: true, timeout: 30000,
      qs: { content_item_id: `eq.${id}`, step: 'eq.review_send', select: 'attempt', order: 'attempt.desc', limit: 1 } });
    await this.helpers.httpRequest({ method: 'POST', url: `${$env.SUPABASE_URL}/rest/v1/pipeline_steps`, headers, json: true, timeout: 30000,
      body: { content_item_id: id, step: 'review_send', attempt: (prev?.[0]?.attempt ?? 0) + 1, status: 'failed', started_at: started, finished_at: new Date().toISOString(), error_type, error_message: message, n8n_execution_id: String($execution.id) } });
  });
}
const logged = await attempt(() => this.helpers.httpRequest({ method: 'POST', url: `${$env.SUPABASE_URL}/rest/v1/error_log`, headers, json: true, timeout: 30000,
  body: { workflow: '32-enviar-revision', content_item_id: id && $('Leer item').isExecuted ? id : null, error_type, error_message: message } }));
await attempt(() => tg('sendMessage', { chat_id: $env.TELEGRAM_ADMIN_CHAT_ID, text: `⚠️ 32 - Enviar a revisión: ${message.slice(0, 500)}\nEjecución: ${$execution.id}` }));
return [{ json: { ok: false, error_type, error_message: message, content_item_id: id, logged } }];
